CREATE COLUMN TABLE "TEST_AP"."ITM4" ("ItemCode" NVARCHAR(50) NOT NULL , "UomType" NVARCHAR(1) DEFAULT 'P' NOT NULL , "UomEntry" INTEGER CS_INT NOT NULL , "PkgCode" INTEGER CS_INT NOT NULL , "Height1" DECIMAL(21,6) CS_FIXED, "Hght1Unit" SMALLINT CS_INT, "Height2" DECIMAL(21,6) CS_FIXED, "Hght2Unit" SMALLINT CS_INT, "Width1" DECIMAL(21,6) CS_FIXED, "Wdth1Unit" SMALLINT CS_INT, "Width2" DECIMAL(21,6) CS_FIXED, "Wdth2Unit" SMALLINT CS_INT, "Length1" DECIMAL(21,6) CS_FIXED, "Len1Unit" SMALLINT CS_INT, "Length2" DECIMAL(21,6) CS_FIXED, "Len2Unit" SMALLINT CS_INT, "Volume" DECIMAL(21,6) CS_FIXED, "VolUnit" SMALLINT CS_INT, "Weight1" DECIMAL(21,6) CS_FIXED, "Wght1Unit" SMALLINT CS_INT, "Weight2" DECIMAL(21,6) CS_FIXED, "Wght2Unit" SMALLINT CS_INT, "QtyPerPack" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("ItemCode", "UomType", "UomEntry", "PkgCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ITM4_PKG_CODE" ON "TEST_AP"."ITM4" ( "PkgCode" ASC );
